-- Lock down questions.ai_answer.
-- The "questions update" policy lets an author update their own row, which would
-- let them write ai_answer and have forged text shown as "Generated by AI".
-- Browser clients (anon / authenticated) may not set or change ai_answer; only
-- /api/ai/community writes it, using the server-only service-role key.
-- Security invoker on purpose: current_user must be the caller's role, not the owner.

create or replace function public.lock_question_ai_answer()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' and new.ai_answer is not null then
      raise exception 'ai_answer can only be set by the server';
    end if;
    if tg_op = 'UPDATE' and new.ai_answer is distinct from old.ai_answer then
      raise exception 'ai_answer can only be set by the server';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists questions_lock_ai_answer on public.questions;
create trigger questions_lock_ai_answer
  before insert or update on public.questions
  for each row execute function public.lock_question_ai_answer();
